<script>
(function(){
    var form=document.getElementById('snb-form');if(!form)return;
    var list=document.getElementById('snb-list'),rows=[].slice.call(list.querySelectorAll('[data-row]')),dragged=null;
    function enabledRows(){return rows.filter(function(row){var check=row.querySelector('[data-show]');return check&&check.checked});}
    function updatePriorities(){rows.forEach(function(row,index){var input=row.querySelector('[data-priority]');if(input)input.value=(index+1)*10;});}
    var previewDevice='desktop';
    function layoutInput(key){var input=form.querySelector('[name="layout['+key+']"]');return input?input.value:'';}
    function renderPreview(){var preview=document.getElementById('snb-preview');preview.innerHTML='';enabledRows().forEach(function(row){var label=row.querySelector('[data-label]'),fallback=row.querySelector('.snb-category'),item=document.createElement('span');item.textContent=label&&label.value.trim()?label.value.trim():fallback.textContent.trim();preview.appendChild(item);});var count=enabledRows().length;document.getElementById('snb-count').textContent=count;document.getElementById('snb-warning').style.display=count>14?'block':'none';}
    function renderDesignPreview(){var preview=document.getElementById('snb-design-preview'),align=layoutInput('alignment').toLowerCase().replace(/_/g,'-'),rowMode=layoutInput('row_mode'),deviceClass=previewDevice==='mobile'?'is-mobile':(previewDevice==='tablet'?'is-tablet':'is-desktop');preview.className='snb-design-preview '+deviceClass;preview.style.justifyContent=align==='space-between'?'space-between':align==='space-around'?'space-around':align==='space-evenly'?'space-evenly':align;preview.style.gap=(previewDevice==='tablet'?layoutInput('tablet_item_gap'):layoutInput('item_gap'))+'px';preview.style.padding=layoutInput('padding_y')+'px '+layoutInput('padding_x')+'px';preview.style.fontSize=(previewDevice==='mobile'?layoutInput('font_size_mobile'):(previewDevice==='tablet'?layoutInput('font_size_tablet'):layoutInput('font_size_desktop')))+'px';preview.style.fontWeight=layoutInput('font_weight');preview.style.flexWrap=rowMode==='SINGLE_ROW'?'nowrap':'wrap';preview.innerHTML='';enabledRows().forEach(function(row){var label=row.querySelector('[data-label]'),fallback=row.querySelector('.snb-category'),item=document.createElement('span');item.textContent=label&&label.value.trim()?label.value.trim():fallback.textContent.trim();preview.appendChild(item);});}
    function updateFilter(){var query=(document.getElementById('snb-search').value||'').trim().toLowerCase(),filter=document.getElementById('snb-filter').value;rows.forEach(function(row){var shown=row.querySelector('[data-show]').checked,matchName=!query||row.getAttribute('data-name').indexOf(query)>-1,matchFilter=filter==='all'||(filter==='shown'&&shown)||(filter==='hidden'&&!shown);row.style.display=matchName&&matchFilter?'':'none';});}
    function bindList(target,selector,prioritySelector){var items=[].slice.call(target.querySelectorAll(selector));items.forEach(function(item){item.addEventListener('dragstart',function(){dragged=item;item.classList.add('is-dragging')});item.addEventListener('dragend',function(){item.classList.remove('is-dragging');dragged=null;target.querySelectorAll(selector).forEach(function(row,index){var priority=row.querySelector(prioritySelector);if(priority)priority.value=(index+1)*10;});renderPreview();});item.addEventListener('dragover',function(e){e.preventDefault();if(dragged&&dragged!==item){var rect=item.getBoundingClientRect();if(e.clientY<rect.top+rect.height/2)target.insertBefore(dragged,item);else target.insertBefore(dragged,item.nextSibling);}});});}
    list.addEventListener('dragover',function(e){e.preventDefault()});bindList(list,'[data-row]','[data-priority]');form.querySelectorAll('[data-sub-list]').forEach(function(subList){bindList(subList,'[data-sub-row]','input[type=number]');});
    document.getElementById('snb-search').addEventListener('input',updateFilter);document.getElementById('snb-filter').addEventListener('change',updateFilter);form.addEventListener('input',function(e){if(e.target.matches('[data-label],[data-show]')){renderPreview();updateFilter();}if(e.target.name&&e.target.name.indexOf('layout[')===0)renderDesignPreview();});form.addEventListener('change',function(e){if(e.target.name&&e.target.name.indexOf('layout[')===0)renderDesignPreview();});document.querySelectorAll('[data-preview-device]').forEach(function(button){button.addEventListener('click',function(){previewDevice=button.getAttribute('data-preview-device');document.querySelectorAll('[data-preview-device]').forEach(function(item){item.classList.toggle('is-active',item===button);});renderDesignPreview();});});renderPreview();renderDesignPreview();updateFilter();
}());
</script>
@endsection
